CREATE TABLE supply_supplier_receiving_updates(
 tenant_id uuid NOT NULL,shipment_id uuid NOT NULL,version bigint NOT NULL,order_id uuid NOT NULL,source_product text NOT NULL,source_organization_id uuid NOT NULL,source_location_id uuid NOT NULL,buyer_tenant_id uuid NOT NULL,body jsonb NOT NULL,source_event_id uuid NOT NULL,actor_subject text NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,shipment_id,version),UNIQUE(tenant_id,source_event_id),
 CHECK(body->>'shipment_id'IS NOT DISTINCT FROM shipment_id::text AND body->>'order_id'IS NOT DISTINCT FROM order_id::text AND body->>'owner_tenant_id'IS NOT DISTINCT FROM buyer_tenant_id::text AND body->>'version'IS NOT DISTINCT FROM version::text)
);
ALTER TABLE supply_supplier_receiving_updates ENABLE ROW LEVEL SECURITY;ALTER TABLE supply_supplier_receiving_updates FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON supply_supplier_receiving_updates USING(hms_tenant_visible(tenant_id)AND((current_setting('app.supply_order_mode',true)='exchange'AND order_id=NULLIF(current_setting('app.supply_order_id',true),'')::uuid)OR(current_setting('app.supply_order_mode',true)IN('seller_read','seller_write')AND source_product=current_setting('app.supply_order_product',true)AND source_organization_id=NULLIF(current_setting('app.supply_order_organization',true),'')::uuid AND source_location_id=NULLIF(current_setting('app.supply_order_location',true),'')::uuid)))
 WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid AND current_setting('app.supply_order_mode',true)='exchange'AND order_id=NULLIF(current_setting('app.supply_order_id',true),'')::uuid AND buyer_tenant_id::text=current_setting('app.supply_order_origin',true)AND actor_subject='system:supplier-receiving');
CREATE TRIGGER supply_supplier_receiving_updates_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON supply_supplier_receiving_updates FOR EACH STATEMENT EXECUTE FUNCTION supply_history_immutable();
CREATE INDEX ON supply_supplier_receiving_updates(tenant_id,order_id,shipment_id,version DESC);
CREATE TABLE supply_supplier_discrepancy_responses(
 tenant_id uuid NOT NULL,id uuid NOT NULL,order_id uuid NOT NULL,shipment_id uuid NOT NULL,summary_version bigint NOT NULL,source_product text NOT NULL,source_organization_id uuid NOT NULL,source_location_id uuid NOT NULL,response text NOT NULL CHECK(response IN('confirmed','disputed')),reason text NOT NULL CHECK(length(reason)BETWEEN 1 AND 500),actor_subject text NOT NULL,actor_staff_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,shipment_id,summary_version),FOREIGN KEY(tenant_id,shipment_id,summary_version)REFERENCES supply_supplier_receiving_updates(tenant_id,shipment_id,version)ON DELETE RESTRICT
);
ALTER TABLE supply_supplier_discrepancy_responses ENABLE ROW LEVEL SECURITY;ALTER TABLE supply_supplier_discrepancy_responses FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON supply_supplier_discrepancy_responses USING(hms_tenant_visible(tenant_id)AND current_setting('app.supply_order_mode',true)IN('seller_read','seller_write')AND source_product=current_setting('app.supply_order_product',true)AND source_organization_id=NULLIF(current_setting('app.supply_order_organization',true),'')::uuid AND source_location_id=NULLIF(current_setting('app.supply_order_location',true),'')::uuid)
 WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid AND current_setting('app.supply_order_mode',true)='seller_write'AND source_product=current_setting('app.supply_order_product',true)AND source_organization_id=NULLIF(current_setting('app.supply_order_organization',true),'')::uuid AND source_location_id=NULLIF(current_setting('app.supply_order_location',true),'')::uuid AND actor_subject=current_setting('app.actor_subject',true)AND actor_staff_id=NULLIF(current_setting('app.supply_order_actor_staff',true),'')::uuid);
CREATE TRIGGER supply_supplier_discrepancy_response_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON supply_supplier_discrepancy_responses FOR EACH STATEMENT EXECUTE FUNCTION supply_history_immutable();
CREATE TRIGGER supply_supplier_discrepancy_response_audit AFTER INSERT ON supply_supplier_discrepancy_responses FOR EACH ROW EXECUTE FUNCTION audit_record_change();
